 * @category constructors
 * @since 1.0.0
 */
export const credentialSecret = (credentials) => (credential) => Effect.mapError(credentials.resolve(Redacted.value(credential)), (error) => error._tag === "/control/Unauthorized"
    ? error
    : new Unauthorized({ message: `credential ${Redacted.value(credential).name} is unavailable` }));
