        name: config.name,
        schema: Schema.Unknown,
        ...(json.fingerprintHeaders === undefined ? {} : { fingerprintHeaders: json.fingerprintHeaders }),
        verify: json.verify,
        decode: (raw) => Effect.flatMap(json.decode(raw), (payload) => Effect.flatMap(Effect.catch(Effect.try({
            try: () => config.decode(raw, payload),
