/**
 * A route that starts `flowId` with the event as its input.
 *
 * @category constructors
 * @since 1.0.0
 */
export const startFlow = (flowId) => (event) => Effect.succeed({ _tag: "Start", flowId, input: event });
/**
 * A route that signals `runId` with the event's signal name and payload.
 *
 * @category constructors
 * @since 1.0.0
 */
export const signalRun = (runId) => (event) => Effect.succeed({ _tag: "Signal", runId, signal: SignalName.toSignalPayload(event) });

/**
 * Durable cursor persistence for polling sources.
 *
 * A polling source is only as safe as its cursor. The contract is that a
 * proposed cursor reaches the store *after* the batch it acknowledges has been
 * handled, so a process that dies mid-batch re-polls that batch on restart
 * instead of skipping it. The store itself is deliberately dumb: get, set, and
 * nothing else.
 *
 * @since 1.0.0
