        get: (sourceId) => Effect.mapError(Effect.map(sql `SELECT cursor FROM smithers_integration_cursors WHERE source_id = ${sourceId}`, (rows) => rows[0]?.cursor ?? null), (cause) => storeError("read", sourceId, cause)),
